def numbersWithDigitGap(n, k):
    res = []

    def go(value, last, left):
        if left == 0:
            res.append(value)
            return
        nxt = {last + k, last - k}
        for d in nxt:
            if 0 <= d <= 9:
                go(value * 10 + d, d, left - 1)

    for first in range(1, 10):
        go(first, first, n - 1)
    return res
